<script setup lang="ts">
import { ref } from 'vue'
import AuthMessage from '@/components/auth/AuthMessage.vue'; import AuthShell from '@/components/auth/AuthShell.vue'; import PrimaryButton from '@/components/auth/PrimaryButton.vue'; import { authRequest, errorText } from '@/lib/auth'
const props = defineProps<{ token: string }>(); const password = ref(''); const confirmation = ref(''); const loading = ref(false); const message = ref(''); const success = ref(false)
async function submit() { loading.value = true; const { response, payload } = await authRequest('/auth/reset-password', { token: props.token, password: password.value, password_confirmation: confirmation.value }); loading.value = false; success.value = response.ok; message.value = response.ok ? 'Password berhasil diubah. Silakan masuk dengan password baru Anda.' : errorText(payload) }
</script>
<template><AuthShell title="Buat password baru" subtitle="Gunakan password unik untuk melindungi akun Anda."><form class="mt-8" @submit.prevent="submit"><label for="password" class="text-sm font-medium">Password baru</label><input id="password" v-model="password" type="password" autocomplete="new-password" required class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-[#0b355d] focus:ring-[#0b355d]" /><label for="confirm" class="mt-5 block text-sm font-medium">Konfirmasi password baru</label><input id="confirm" v-model="confirmation" type="password" autocomplete="new-password" required class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-[#0b355d] focus:ring-[#0b355d]" /><AuthMessage :message="message" :tone="success ? 'success' : 'error'" /><PrimaryButton :loading="loading">Simpan password baru</PrimaryButton></form></AuthShell></template>
